import json
import math
import statistics as st

dates = ["2024-03-01", "2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08"]
c = {
    "AAPL": [180.0, 182.5, 179.0, 176.5, 178.0, 181.25],
    "MSFT": [400.0, 402.0, 405.5, 407.0, 410.25, 412.0],
}
r = {t: [math.log(v[i] / v[i - 1]) for i in range(1, 6)] for t, v in c.items()}
w = 2
vol = {
    t: [None if i < w else st.stdev(x[i - w : i]) * math.sqrt(252) for i in range(5)]
    for t, x in r.items()
}
print(json.dumps(r, indent=1))
print(json.dumps(vol, indent=1))
x = r["AAPL"]
ar = 252 * st.mean(x)
av = math.sqrt(252) * st.stdev(x)
print(json.dumps({"ann_return": ar, "ann_vol": av, "sharpe": ar / av, "last_vol": vol["AAPL"][-1]}))
for t in c:
    wealth = [1.0]
    for v in r[t]:
        wealth.append(wealth[-1] * math.exp(v))
    peak, pd, best = wealth[0], dates[0], (0.0, dates[0], dates[0])
    for d, p in zip(dates, wealth):
        if p > peak:
            peak, pd = p, d
        dd = p / peak - 1
        if dd < best[0]:
            best = (dd, pd, d)
    print(t, json.dumps(best))

